package solution

func Solve(nums []int) map[string][]int {
	groups := make(map[string][]int) // writable map of slices
	for _, n := range nums {
		key := "odd"
		if n%2 == 0 {
			key = "even"
		}
		// appending to a missing key works: the value reads as a nil slice
		groups[key] = append(groups[key], n)
	}
	return groups
}

