func TwoSum(nums []int, target int) (int, int, bool) {
	seen := make(map[int]int, len(nums)) // value -> index
	for i, n := range nums {
		if j, ok := seen[target-n]; ok { // complement already seen?
			return j, i, true
		}
		seen[n] = i // record this value's index
	}
	return 0, 0, false // no pair found
}
